1	package com.loja.checkout;
2	
3	import com.loja.checkout.ResumoRequest.ItemRequest;
4	import com.loja.checkout.clube.NivelClube;
5	import com.loja.checkout.cupom.Cupom;
6	import com.loja.checkout.entrega.ModalidadeEntrega;
7	import com.loja.checkout.pagamento.FormaPagamento;
8	import com.loja.checkout.pagamento.ResultadoPagamento;
9	import org.springframework.stereotype.Service;
10	
11	import java.math.BigDecimal;
12	import java.util.List;
13	import java.util.Map;
14	import java.util.function.Function;
15	import java.util.stream.Collectors;
16	
17	@Service
18	public class CheckoutService {
19	
20	    private final Map<String, ModalidadeEntrega> modalidades;
21	    private final Map<String, Cupom> cupons;
22	    private final Map<String, NivelClube> niveis;
23	    private final Map<String, FormaPagamento> formasPagamento;
24	
25	    public CheckoutService(List<ModalidadeEntrega> modalidades,
26	                           List<Cupom> cupons,
27	                           List<NivelClube> niveis,
28	                           List<FormaPagamento> formasPagamento) {
29	        this.modalidades = modalidades.stream()
30	                .collect(Collectors.toMap(ModalidadeEntrega::codigo, Function.identity()));
31	        this.cupons = cupons.stream()
32	                .collect(Collectors.toMap(Cupom::codigo, Function.identity()));
33	        this.niveis = niveis.stream()
34	                .collect(Collectors.toMap(NivelClube::codigo, Function.identity()));
35	        this.formasPagamento = formasPagamento.stream()
36	                .collect(Collectors.toMap(FormaPagamento::codigo, Function.identity()));
37	    }
38	
39	    public ResumoResponse calcular(ResumoRequest request) {
40	        validarItens(request.itens());
41	
42	        NivelClube nivel = encontrar(niveis, request.nivelClube(), "NIVEL_CLUBE_INVALIDO");
43	
44	        Regiao regiao = encontrarRegiao(request.regiao());
45	
46	        ModalidadeEntrega modalidade = encontrar(modalidades, request.modalidadeEntrega(),
47	                "MODALIDADE_INVALIDA");
48	
49	        BigDecimal pesoTotal = calcularPesoTotal(request.itens());
50	        if (!modalidade.disponivel(pesoTotal)) {
51	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
52	        }
53	
54	        BigDecimal subtotal = calcularSubtotal(request.itens());
55	
56	        Cupom cupom = null;
57	        if (request.cupom() != null && !request.cupom().isBlank()) {
58	            cupom = encontrar(cupons, request.cupom(), "CUPOM_INVALIDO");
59	            if (!cupom.aplicavel(request.itens(), subtotal)) {
60	                throw new CheckoutException("CUPOM_NAO_APLICAVEL");
61	            }
62	        }
63	
64	        int parcelas = request.parcelas() != null ? request.parcelas() : 1;
65	        FormaPagamento formaPagamento = encontrar(formasPagamento, request.formaPagamento(),
66	                "FORMA_PAGAMENTO_INVALIDA");
67	        if (!formaPagamento.parcelamentoValido(parcelas)) {
68	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
69	        }
70	
71	        BigDecimal frete = modalidade.calcularFrete(pesoTotal);
72	        if (nivel.freteGratis()) {
73	            frete = BigDecimal.ZERO.setScale(2);
74	        }
75	
76	        BigDecimal descontoCupom = BigDecimal.ZERO.setScale(2);
77	        if (cupom != null) {
78	            descontoCupom = cupom.calcularDesconto(request.itens(), subtotal, frete);
79	        }
80	
81	        BigDecimal seguro = Moeda.arredondar(subtotal.multiply(regiao.getTaxaSeguro()));
82	
83	        BigDecimal totalPedido = Moeda.arredondar(
84	                subtotal.subtract(descontoCupom).add(frete).add(seguro));
85	
86	        if (!formaPagamento.disponivel(totalPedido)) {
87	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
88	        }
89	
90	        ResultadoPagamento resultado = formaPagamento.calcular(totalPedido, parcelas);
91	
92	        BigDecimal ajuste = Moeda.arredondar(resultado.totalFinal().subtract(totalPedido));
93	        BigDecimal credito = nivel.calcularCredito(subtotal);
94	        boolean brinde = nivel.brinde(subtotal);
95	
96	        return new ResumoResponse(
97	                subtotal,
98	                descontoCupom,
99	                frete,
100	                modalidade.prazoDias(),
101	                seguro,
102	                ajuste,
103	                resultado.totalFinal(),
104	                parcelas,
105	                resultado.valorParcela(),
106	                credito,
107	                brinde);
108	    }
109	
110	    private void validarItens(List<ItemRequest> itens) {
111	        if (itens == null || itens.isEmpty()) {
112	            throw new CheckoutException("PEDIDO_INVALIDO");
113	        }
114	        for (ItemRequest item : itens) {
115	            if (item.precoUnitario() == null
116	                    || item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0
117	                    || item.quantidade() == null
118	                    || item.quantidade() <= 0
119	                    || item.pesoKg() == null
120	                    || item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
121	                throw new CheckoutException("PEDIDO_INVALIDO");
122	            }
123	        }
124	    }
125	
126	    private BigDecimal calcularSubtotal(List<ItemRequest> itens) {
127	        BigDecimal subtotal = BigDecimal.ZERO;
128	        for (ItemRequest item : itens) {
129	            subtotal = subtotal.add(
130	                    item.precoUnitario().multiply(new BigDecimal(item.quantidade())));
131	        }
132	        return Moeda.arredondar(subtotal);
133	    }
134	
135	    private BigDecimal calcularPesoTotal(List<ItemRequest> itens) {
136	        BigDecimal peso = BigDecimal.ZERO;
137	        for (ItemRequest item : itens) {
138	            peso = peso.add(item.pesoKg().multiply(new BigDecimal(item.quantidade())));
139	        }
140	        return peso;
141	    }
142	
143	    private Regiao encontrarRegiao(String codigo) {
144	        if (codigo == null || codigo.isBlank()) {
145	            throw new CheckoutException("REGIAO_INVALIDA");
146	        }
147	        try {
148	            return Regiao.valueOf(codigo);
149	        } catch (IllegalArgumentException e) {
150	            throw new CheckoutException("REGIAO_INVALIDA");
151	        }
152	    }
153	
154	    private <T> T encontrar(Map<String, T> mapa, String codigo, String codigoErro) {
155	        if (codigo == null || codigo.isBlank()) {
156	            throw new CheckoutException(codigoErro);
157	        }
158	        T resultado = mapa.get(codigo);
159	        if (resultado == null) {
160	            throw new CheckoutException(codigoErro);
161	        }
162	        return resultado;
163	    }
164	}
