3	import com.loja.checkout.Moeda;
4	import org.springframework.stereotype.Component;
5	
6	import java.math.BigDecimal;
7	import java.math.MathContext;
8	
9	@Component
10	public class PagamentoCartao implements FormaPagamento {
11	
12	    private static final BigDecimal TAXA_MENSAL = new BigDecimal("0.0199");
13	    private static final int PARCELAS_SEM_JUROS = 3;
14	    private static final int PARCELAS_MAXIMAS = 12;
15	
16	    @Override
17	    public String codigo() {
18	        return "CARTAO";
19	    }
20	
21	    @Override
22	    public boolean parcelamentoValido(int parcelas) {
23	        return parcelas >= 1 && parcelas <= PARCELAS_MAXIMAS;
24	    }
25	
26	    @Override
27	    public boolean disponivel(BigDecimal totalPedido) {
28	        return true;
29	    }
30	
31	    @Override
32	    public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
33	        if (parcelas <= PARCELAS_SEM_JUROS) {
34	            BigDecimal valorParcela = Moeda.arredondar(
35	                    totalPedido.divide(new BigDecimal(parcelas), MathContext.DECIMAL128));
36	            return new ResultadoPagamento(totalPedido, valorParcela);
37	        }
38	
39	        BigDecimal umMaisTaxa = BigDecimal.ONE.add(TAXA_MENSAL);
40	        BigDecimal potencia = umMaisTaxa.pow(parcelas, MathContext.DECIMAL128);
41	        BigDecimal denominador = BigDecimal.ONE.subtract(
42	                BigDecimal.ONE.divide(potencia, MathContext.DECIMAL128));
43	        BigDecimal valorParcela = Moeda.arredondar(
44	                totalPedido.multiply(TAXA_MENSAL).divide(denominador, MathContext.DECIMAL128));
45	        BigDecimal totalFinal = valorParcela.multiply(new BigDecimal(parcelas));
46	        return new ResultadoPagamento(totalFinal, valorParcela);
47	    }
48	}
